sys_script_include.script:
var OnboardingTaskGenerator = Class.create();

OnboardingTaskGenerator.prototype = {

    initialize: function() {
        this.taskTemplates = [
            { type: 'IT Access', name: 'Provision IT access and email account', group: 'IT Help Desk', offsetDays: -3 },
            { type: 'Hardware', name: 'Allocate laptop and peripherals', group: 'Hardware Support', offsetDays: -2 },
            { type: 'ID Card', name: 'Generate employee ID card', group: 'Admin Support', offsetDays: -1 },
            { type: 'Policy Ack', name: 'Send policy acknowledgment forms', group: 'IT Help Desk', offsetDays: 0 },
            { type: 'Buddy Assignment', name: 'Assign onboarding buddy', group: 'Software Support', offsetDays: -2 },
            { type: 'Week 1 Schedule', name: 'Prepare first-week schedule and orientation', group: 'Infrastructure Support', offsetDays: -1 }
        ];
    },

    generateTasks: function(newHireSysId, joiningDateStr) {
        var created = [];

        for (var i = 0; i < this.taskTemplates.length; i++) {
            var tmpl = this.taskTemplates[i];
            var dueDate = this._calculateDueDate(joiningDateStr, tmpl.offsetDays);

            var groupGR = new GlideRecord('sys_user_group');
            groupGR.addQuery('name', tmpl.group);
            groupGR.setLimit(1);
            groupGR.query();

            // FIXED: correct scoped table name
            var taskGR = new GlideRecord('x_2064375_onboar_0_onboarding_task');
            taskGR.initialize();
            taskGR.u_parent_hire = newHireSysId;
            taskGR.u_task_name = tmpl.name;
            taskGR.u_task_type = tmpl.type;
            taskGR.u_due_date = dueDate;
            taskGR.u_state = 'Open';

            if (groupGR.next()) {
                taskGR.u_assignment_group = groupGR.sys_id;
            } else {
                gs.warn('OnboardingTaskGenerator: Group not found: ' + tmpl.group);
            }

            var newSysId = taskGR.insert();
            gs.info('OnboardingTaskGenerator: Created task [' + tmpl.name + '] sys_id: ' + newSysId);
            created.push(newSysId);
        }

        gs.info('OnboardingTaskGenerator: Total tasks created: ' + created.length);
        return created;
    },

    _calculateDueDate: function(joiningDateStr, offsetDays) {
        var gdt = new GlideDateTime(joiningDateStr);
        gdt.addDaysLocalTime(offsetDays);
        return gdt.getDate().toString();
    },

    getCompletionPercentage: function(newHireSysId) {
        var total = 0;
        var closed = 0;

        // FIXED: correct scoped table name
        var gr = new GlideRecord('x_2064375_onboar_0_onboarding_task');
        gr.addQuery('u_parent_hire', newHireSysId);
        gr.query();

        while (gr.next()) {
            total++;
            if (gr.u_state == 'Closed') {
                closed++;
            }
        }

        if (total === 0) return 0;
        return Math.round((closed / total) * 100);
    },

    type: 'OnboardingTaskGenerator'
};
